begin;
\ir ../fixtures/analyzer.inc
select extensions.no_plan();
select public.set_token_analyzer_enabled(true);
update analyzer_case set r=public.analyzer_reserve_delivery(f->'input',f->'resolution');
set local role service_role;
update analyzer_case set f=jsonb_set(f,'{manifest,resolvedToken}',(select public.analyzer_attest_resolution(r->>'delivery_key',f->'input',f->'resolution',repeat('a',64),'token-analyzer-live-collector-v2')->'resolution'));
update analyzer_case set p=jsonb_set(p,'{resolvedToken}',f->'manifest'->'resolvedToken');
set local role authenticated;
select extensions.is((select r->>'status' from analyzer_case),'NEW','Reservation precedes collection');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{observations}','[{"key":"liquidity","label":"Liquidity","value":"100","evidenceClass":"VERIFIED_DATA","source":"chain","observedAt":"2026-09-20T00:00:00Z","evidenceId":"liq1","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","provenance":[{"source":"chain","kind":"DIRECT_CHAIN","reference":"0x0000000000000000000000000000000000000002","referenceType":"POOL","capturedAt":"2026-09-20T00:00:00Z"}]}]'::jsonb))$$,'23P01',null,'missing observation state rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{observations}','[{"key":"liquidity","label":"Liquidity","value":"100","state":null,"evidenceClass":"VERIFIED_DATA","source":"chain","observedAt":"2026-09-20T00:00:00Z","evidenceId":"liq1","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","provenance":[{"source":"chain","kind":"DIRECT_CHAIN","reference":"0x0000000000000000000000000000000000000002","referenceType":"POOL","capturedAt":"2026-09-20T00:00:00Z"}]}]'::jsonb))$$,'23P01',null,'NULL state supported claim rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{observations}','[{"key":"liquidity","label":"Liquidity","value":"100","state":"UNKNOWN","evidenceClass":"VERIFIED_DATA","source":"chain","observedAt":"2026-09-20T00:00:00Z","evidenceId":"liq1","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","provenance":[{"source":"chain","kind":"DIRECT_CHAIN","reference":"0x0000000000000000000000000000000000000002","referenceType":"POOL","capturedAt":"2026-09-20T00:00:00Z"}]}]'::jsonb))$$,'23P01',null,'unknown state rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{observations}','[{"key":"liquidity","label":"Liquidity","value":"100","state":"UNAVAILABLE","evidenceClass":"VERIFIED_DATA","source":"chain","observedAt":"2026-09-20T00:00:00Z","evidenceId":"liq1","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","provenance":[{"source":"chain","kind":"DIRECT_CHAIN","reference":"0x0000000000000000000000000000000000000002","referenceType":"POOL","capturedAt":"2026-09-20T00:00:00Z"}]}]'::jsonb))$$,'23P01',null,'unavailable state rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{observations}','[{"key":"liquidity","label":"Liquidity","value":"100","state":"STALE","evidenceClass":"VERIFIED_DATA","source":"chain","observedAt":"2026-09-20T00:00:00Z","evidenceId":"liq1","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","provenance":[{"source":"chain","kind":"DIRECT_CHAIN","reference":"0x0000000000000000000000000000000000000002","referenceType":"POOL","capturedAt":"2026-09-20T00:00:00Z"}]}]'::jsonb))$$,'23P01',null,'stale state rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{claims}','[{"conclusionType":"CLAIM_SUPPORTED","claim":"liquidity (0x0000000000000000000000000000000000000002) = 100","source":"chain","verification":"SUPPORTED","evidenceRefs":["missing"],"evidenceType":"VERIFIED_DATA","field":"liquidity","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","value":"100"}]'::jsonb))$$,'23P01',null,'nonexistent claim evidence rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{whyMoving}','[{"classification":"VERIFIED_FACT","field":"wallet","evidenceRefs":["liq1"],"value":"999"}]'::jsonb))$$,'23P01',null,'wallet explanation using liquidity rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{whyMoving}','[{"classification":null,"evidenceRefs":["missing"]}]'::jsonb))$$,'23P01',null,'null explanation classification rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{riskFactors}','[{"key":"creator_exit","state":"PRESENT","evidenceRefs":["liq1"]}]'::jsonb))$$,'23P01',null,'creator exit using liquidity rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{riskFactors}','[{"key":"creator_exit","state":"PRESENT","evidenceRefs":["missing"]}]'::jsonb))$$,'23P01',null,'nonexistent risk reference rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{manifestFormatVersion}','"1"'::jsonb))$$,'23P01',null,'numeric version string rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),((select p from analyzer_case) #- '{versions}'))$$,'23P01',null,'missing registry rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{methodologyVersion}','"fake"'::jsonb))$$,'23P01',null,'nested invented methodology rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{result}','{"score":{"status":"SCORED","value":99}}'::jsonb))$$,'23P01',null,'forged result rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{result}','{"aiInterpretation":{"status":"AVAILABLE"}}'::jsonb))$$,'23P01',null,'forged AI rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{manifestHash}','"ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff"'::jsonb))$$,'23P01',null,'forged hash rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{input,rawHash}','"ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff"'::jsonb))$$,'23P01',null,'nested input mismatch rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{claims}','[{"conclusionType":"CLAIM_SUPPORTED","claim":"liquidity (0x0000000000000000000000000000000000000002) = 100","source":"chain","verification":"SUPPORTED","evidenceRefs":["liq1"],"evidenceType":"VERIFIED_DATA","field":"liquidity","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","value":"100"}]'::jsonb))$$,'23P01',null,'omitted identity rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{claims}','[{"conclusionType":"CLAIM_SUPPORTED","claim":"liquidity (0x0000000000000000000000000000000000000002) = 100","source":"chain","verification":"SUPPORTED","evidenceRefs":["liq1"],"evidenceType":"VERIFIED_DATA","field":"liquidity","identity":null,"identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","value":"100"}]'::jsonb))$$,'23P01',null,'null identity rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{claims}','[{"conclusionType":"CLAIM_SUPPORTED","claim":"liquidity (0x0000000000000000000000000000000000000002) = 100","source":"chain","verification":"SUPPORTED","evidenceRefs":["liq1"],"evidenceType":"VERIFIED_DATA","field":"liquidity","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","value":"999"}]'::jsonb))$$,'23P01',null,'wrong value rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{observations}','[{"key":"liquidity","label":"Liquidity","value":"100","state":"AVAILABLE","evidenceClass":"VERIFIED_DATA","source":"chain","observedAt":"2026-09-20T00:00:00Z","evidenceId":"liq1","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","provenance":[{"source":"chain","kind":"DIRECT_CHAIN","reference":"0x0000000000000000000000000000000000000003","referenceType":"POOL","capturedAt":"2026-09-20T00:00:00Z"}]}]'::jsonb))$$,'23P01',null,'wrong pool rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set(jsonb_set((select p from analyzer_case),'{observations}','[{"key":"liquidity","label":"Liquidity","value":"100","state":"AVAILABLE","evidenceClass":"VERIFIED_DATA","source":"chain","observedAt":"2026-09-20T00:00:00Z","evidenceId":"0x0000000000000000000000000000000000000003","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","provenance":[{"source":"chain","kind":"DIRECT_CHAIN","reference":"0x0000000000000000000000000000000000000003","referenceType":"POOL","capturedAt":"2026-09-20T00:00:00Z"}]}]'::jsonb),'{claims}','[{"conclusionType":"CLAIM_SUPPORTED","claim":"liquidity (0x0000000000000000000000000000000000000002) = 100","source":"chain","verification":"SUPPORTED","evidenceRefs":["0x0000000000000000000000000000000000000003"],"evidenceType":"VERIFIED_DATA","field":"liquidity","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","value":"100"}]'::jsonb))$$,'23P01',null,'evidence ID substitutes pool rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{observations}','[{"key":"liquidity","label":"Liquidity","value":"100","state":"AVAILABLE","evidenceClass":"VERIFIED_DATA","source":"chain","observedAt":"2026-09-20T00:00:00Z","evidenceId":"liq1","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","provenance":[{"source":"chain","kind":"CONTEXTUAL_PROPRIETARY","reference":"0x0000000000000000000000000000000000000002","referenceType":"POOL","capturedAt":"2026-09-20T00:00:00Z"}]}]'::jsonb))$$,'23P01',null,'contextual VERIFIED_DATA rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{claims}','[{"conclusionType":"CLAIM_SUPPORTED","claim":"Creator exited","source":"chain","verification":"SUPPORTED","evidenceRefs":["liq1"],"evidenceType":"VERIFIED_DATA","field":"liquidity","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","value":"100"}]'::jsonb))$$,'23P01',null,'unsupported positive prose rejected');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select p from analyzer_case),'{topTrades}','[{"key":"trade","label":"Liquidity","value":"999","state":"AVAILABLE","evidenceClass":"VERIFIED_DATA","source":"chain","observedAt":"2026-09-20T00:00:00Z","evidenceId":"liq1","identity":"0x0000000000000000000000000000000000000002","identityType":"POOL","tokenId":"ethereum:0x0000000000000000000000000000000000000001","provenance":[{"source":"chain","kind":"DIRECT_CHAIN","reference":"0x0000000000000000000000000000000000000002","referenceType":"POOL","capturedAt":"2026-09-20T00:00:00Z"}]}]'::jsonb))$$,'23P01',null,'trade evidence reuse rejected');
update analyzer_case set d1=public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),(select f->'manifest' from analyzer_case));
select extensions.is((select d1->>'analysis_version' from analyzer_case),'1','D1 version 1');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select f->'manifest' from analyzer_case),'{capturedAt}','"2026-09-21T00:00:00Z"'))$$,'55000',null,'Changed timestamp cannot resubmit sealed delivery');
select extensions.throws_ok($$select public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),(select f->'manifest' from analyzer_case)||'{"analysisVersion":999}'::jsonb)$$,'55000',null,'analysisVersion 999 cannot resubmit sealed delivery');
select extensions.throws_ok($$select public.analyzer_get_delivery_receipt(repeat('1',64),'{"analysisVersion":999}'::jsonb)$$,'42883',null,'Retry accepts only key');
update analyzer_case set r=public.analyzer_start_fresh_analysis(f->'input',f->'resolution','00000000-0000-4000-8000-000000000002');
update analyzer_case set d2=public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),(select p from analyzer_case));
select extensions.is((select d2->>'analysis_version' from analyzer_case),'2','Fresh D2 version 2');
update analyzer_case set r=public.analyzer_start_reanalysis(d2->>'delivery_key','00000000-0000-4000-8000-000000000003','Deliberate reinterpretation');
update analyzer_case set d3=public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),null);
select extensions.is((select d3->>'analysis_version' from analyzer_case),'3','Reanalysis D3 version 3');
select extensions.is((select d2->>'manifest_hash' from analyzer_case),(select d3->>'manifest_hash' from analyzer_case),'D2 D3 share H2');
select extensions.isnt((select d2->>'delivery_key' from analyzer_case),(select d3->>'delivery_key' from analyzer_case),'H2 deliveries distinct');
select extensions.is((select public.analyzer_get_delivery_receipt(d1->>'delivery_key') from analyzer_case),(select d1 from analyzer_case),'d1 exact retry after v3');
select extensions.is((select public.analyzer_get_delivery_receipt(d2->>'delivery_key') from analyzer_case),(select d2 from analyzer_case),'d2 exact retry after v3');
select extensions.is((select public.analyzer_get_delivery_receipt(d3->>'delivery_key') from analyzer_case),(select d3 from analyzer_case),'d3 exact retry after v3');
update analyzer_case set r=public.analyzer_start_fresh_analysis(f->'input',f->'resolution','00000000-0000-4000-8000-000000000004');
update analyzer_case set d4=public.analyzer_complete_delivery((select r->>'delivery_key' from analyzer_case),(select (r->>'owner_token')::uuid from analyzer_case),jsonb_set((select f->'manifest' from analyzer_case),'{capturedAt}','"2026-09-21T00:00:00Z"'));
select extensions.is((select public.analyzer_get_delivery_receipt(d4->>'delivery_key') from analyzer_case),(select d4 from analyzer_case),'Capture-time delivery exact retry');
select extensions.is((select public.analyzer_get_analysis_by_version((d1->>'request_id')::uuid,1) from analyzer_case),(select d1 from analyzer_case),'Historical exact');
select extensions.is((select public.analyzer_get_latest_analysis((d1->>'request_id')::uuid) from analyzer_case),(select d4 from analyzer_case),'Latest explicit');
reset role;
select extensions.ok((select bool_and(a.evidence_revision=m.manifest_version and a.evidence_revision=(m.manifest->>'evidenceRevision')::integer and a.evidence_revision=(a.result->>'evidenceRevision')::integer) from public.analyzer_analyses a join public.analyzer_evidence_manifests m on m.id=a.evidence_manifest_id),'Revision consistency');
select extensions.throws_ok($$update public.analyzer_deliveries set operation=operation$$,'55000',null,'Delivery immutable');
select extensions.throws_ok($$delete from public.analyzer_deliveries$$,'55000',null,'Delivery undeletable');
select extensions.throws_ok($$update public.analyzer_evidence_manifests set manifest=manifest$$,'55000',null,'Evidence immutable');
select extensions.throws_ok($$update public.analyzer_analyses set result=result$$,'55000',null,'Analysis immutable');
select * from extensions.finish();
rollback;
